package com.greenlink.security; import java.util.Collection; import org.springframework.security.core.GrantedAuthority; import org.springframework.security.core.userdetails.UserDetails;
public class AppUserPrincipal implements UserDetails { private final String id,email,password; private final boolean provider; public AppUserPrincipal(String id,String email,String password,boolean provider){this.id=id;this.email=email;this.password=password;this.provider=provider;} public String getId(){return id;} public boolean isProvider(){return provider;} public Collection<? extends GrantedAuthority> getAuthorities(){return java.util.List.of();} public String getPassword(){return password;} public String getUsername(){return email;} public boolean isAccountNonExpired(){return true;} public boolean isAccountNonLocked(){return true;} public boolean isCredentialsNonExpired(){return true;} public boolean isEnabled(){return true;} }
